    const AnimalLootDefinition *FindAnimalLoot(std::string_view actorClass) {
        const auto found = std::find_if(g_AnimalLoot.begin(), g_AnimalLoot.end(), [actorClass](const auto &row) {
            return row.actorClass == actorClass;
        });
        return found != g_AnimalLoot.end() ? &*found : nullptr;
    }
    const AnimalSoulDefinition *FindAnimalSoul(std::string_view soul) {
        const auto found = std::lower_bound(g_AnimalSouls.begin(), g_AnimalSouls.end(), soul, [](const auto &row, std::string_view value) {
            return row.soul < value;
        });
        return found != g_AnimalSouls.end() && found->soul == soul ? &*found : nullptr;
    }

    const AnimalSoulDefinition *FindAnimalSoulByName(std::string_view name) {
        const AnimalSoulDefinition *found = nullptr;
        for (const auto &row : g_AnimalSouls) {
            if (row.name != name)
                continue;
            if (found != nullptr && (row.actorClass != found->actorClass || row.lootable != found->lootable))
                return nullptr;
            found = &row;
        }
        return found;
    }

